<?php

declare(strict_types=1);

require_once __DIR__ . '/Database.php';
require_once __DIR__ . '/Auth.php';
require_once __DIR__ . '/AppNavigation.php';
require_once __DIR__ . '/CommunicationReadStateService.php';
require_once __DIR__ . '/MessageAttachmentService.php';
require_once __DIR__ . '/StorageService.php';

final class CommunicationExperience
{
    private const ROUTES = ['/channels', '/channels/view', '/messages', '/messages/new', '/messages/thread', '/messages/attachment'];

    public static function handles(string $route): bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath): never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=self::currentUser($db);$userId=(int)$user['id'];$_SESSION['communication_csrf']??=bin2hex(random_bytes(24));
        if($route==='/messages/attachment'){$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$attachment=MessageAttachmentService::attachmentForParticipant($db,(int)$id,$userId);if(!$attachment){http_response_code(404);exit('Attachment unavailable.');}StorageService::stream(dirname(__DIR__),$attachment,true);}
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$user,$basePath);
        $query=trim((string)($_GET['q']??''));if(mb_strlen($query)>100)$query=mb_substr($query,0,100);$channels=self::channels($db);$conversations=self::conversations($db,$userId,$query);$recipients=$route==='/messages/new'?self::availableRecipients($db,$user):[];$selectedChannel=null;$selectedConversation=null;
        if($route==='/channels/view'){$channelId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$selectedChannel=self::channelById($db,(int)$channelId);}if($route==='/messages/thread'){$conversationId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$selectedConversation=self::conversationById($db,$userId,(int)$conversationId);}self::page($route,$basePath,$user,$channels,$conversations,$recipients,$selectedChannel,$selectedConversation,$query);
    }

    private static function handlePost(PDO $db,array $user,string $basePath): never
    {
        $token=(string)($_POST['csrf_token']??'');if(!hash_equals((string)($_SESSION['communication_csrf']??''),$token)){self::flash('error','Your session token expired. Please try again.');self::redirect($basePath.'/messages');}$action=(string)($_POST['action']??'');$userId=(int)$user['id'];$upload=$_FILES['attachment']??[];
        if($action==='create_conversation'){$recipientId=filter_input(INPUT_POST,'recipient_id',FILTER_VALIDATE_INT)?:0;$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['body']??''));try{$conversationId=self::createConversation($db,$user,(int)$recipientId,$subject,$body,$upload);self::flash('success','Conversation created with the required safety participants included.');self::redirect($basePath.'/messages/thread?id='.$conversationId);}catch(RuntimeException $e){self::flash('error',$e->getMessage());self::redirect($basePath.'/messages/new');}}
        $conversationId=filter_input(INPUT_POST,'conversation_id',FILTER_VALIDATE_INT)?:0;if($action!=='send_message'||$conversationId<1){self::flash('error','That message action could not be completed.');self::redirect($basePath.'/messages');}$body=trim((string)($_POST['body']??''));try{$attached=self::sendMessage($db,$userId,(int)$conversationId,$body,$upload);self::flash('success',$attached?'Message and attachment sent to everyone in this conversation.':'Message sent to everyone in this conversation.');}catch(RuntimeException $e){self::flash('error',$e->getMessage());}self::redirect($basePath.'/messages/thread?id='.(int)$conversationId);
    }

    private static function createConversation(PDO $db,array $initiator,int $recipientId,string $subject,string $body,array $upload): int
    {
        if($recipientId<1||$recipientId===(int)$initiator['id'])throw new RuntimeException('Choose another active CTSMD member.');if($subject===''||mb_strlen($subject)>190)throw new RuntimeException('Add a subject up to 190 characters.');if($body===''||mb_strlen($body)>4000)throw new RuntimeException('Add an opening message up to 4,000 characters.');
        $recipientStmt=$db->prepare("SELECT id,CONCAT(first_name,' ',last_name) name,display_role role,active FROM users WHERE id=:id LIMIT 1");$recipientStmt->execute(['id'=>$recipientId]);$recipient=$recipientStmt->fetch();if(!$recipient||!(bool)$recipient['active'])throw new RuntimeException('That recipient is not available.');$recipient['roles']=Auth::roles($db,$recipientId);
        $initiatorStudent=self::isStudentUser($initiator);$recipientStudent=self::isStudentUser($recipient);if($initiatorStudent&&$recipientStudent)throw new RuntimeException('Student-to-student direct messaging is not available.');$type='direct';$participants=[];
        if($initiatorStudent||$recipientStudent){$student=$initiatorStudent?$initiator:$recipient;$adult=$initiatorStudent?$recipient:$initiator;if(!self::isStaffUser($adult))throw new RuntimeException('New student conversations must involve CTSMD staff. Family-to-student direct threads are not created here.');$guardian=self::primaryGuardian($db,(int)$student['id']);if(!$guardian)throw new RuntimeException('This student does not have an active guardian relationship. Messaging cannot begin until staff repairs that relationship.');if((int)$guardian['id']===(int)$adult['id'])throw new RuntimeException('A separate active guardian is required before this student conversation can begin.');$type='safeguarded';$participants=[['id'=>(int)$adult['id'],'participant_role'=>'adult','guardian_required'=>0],['id'=>(int)$student['id'],'participant_role'=>'student','guardian_required'=>0],['id'=>(int)$guardian['id'],'participant_role'=>'guardian','guardian_required'=>1]];}else{$participants=[['id'=>(int)$initiator['id'],'participant_role'=>'adult','guardian_required'=>0],['id'=>(int)$recipient['id'],'participant_role'=>'adult','guardian_required'=>0]];}
        self::assertConversationSafe($type,array_map(static fn(array $p):array=>$p+['active'=>1],$participants));
        $db->beginTransaction();try{$insertConversation=$db->prepare('INSERT INTO conversations (subject,conversation_type,created_at) VALUES (:subject,:type,CURRENT_TIMESTAMP)');$insertConversation->execute(['subject'=>$subject,'type'=>$type]);$conversationId=(int)$db->lastInsertId();$insertParticipant=$db->prepare('INSERT INTO conversation_participants (conversation_id,user_id,participant_role,guardian_required) VALUES (:conversation,:user,:role,:guardian)');foreach($participants as $p)$insertParticipant->execute(['conversation'=>$conversationId,'user'=>$p['id'],'role'=>$p['participant_role'],'guardian'=>$p['guardian_required']]);$insertMessage=$db->prepare('INSERT INTO messages (conversation_id,sender_user_id,body,created_at) VALUES (:conversation,:sender,:body,CURRENT_TIMESTAMP)');$insertMessage->execute(['conversation'=>$conversationId,'sender'=>(int)$initiator['id'],'body'=>$body]);$messageId=(int)$db->lastInsertId();MessageAttachmentService::attachUpload($db,dirname(__DIR__),$messageId,(int)$initiator['id'],$upload);$db->commit();return$conversationId;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e instanceof RuntimeException?$e:new RuntimeException('We could not create that conversation. Please try again.');}
    }

    private static function sendMessage(PDO $db,int $userId,int $conversationId,string $body,array $upload):bool
    {
        if($body===''||mb_strlen($body)>4000)throw new RuntimeException($body===''?'Write a message before sending.':'Messages are limited to 4,000 characters.');$db->beginTransaction();try{$conversationStmt=$db->prepare('SELECT id,conversation_type FROM conversations WHERE id=:id FOR UPDATE');$conversationStmt->execute(['id'=>$conversationId]);$conversation=$conversationStmt->fetch();if(!$conversation)throw new RuntimeException('That conversation no longer exists.');$membershipStmt=$db->prepare('SELECT participant_role FROM conversation_participants WHERE conversation_id=:conversation AND user_id=:user');$membershipStmt->execute(['conversation'=>$conversationId,'user'=>$userId]);if(!$membershipStmt->fetch())throw new RuntimeException('You do not have access to that conversation.');$participantsStmt=$db->prepare('SELECT cp.user_id,cp.participant_role,cp.guardian_required,u.active FROM conversation_participants cp JOIN users u ON u.id=cp.user_id WHERE cp.conversation_id=:conversation FOR UPDATE');$participantsStmt->execute(['conversation'=>$conversationId]);self::assertConversationSafe((string)$conversation['conversation_type'],$participantsStmt->fetchAll());$insert=$db->prepare('INSERT INTO messages (conversation_id,sender_user_id,body,created_at) VALUES (:conversation,:sender,:body,CURRENT_TIMESTAMP)');$insert->execute(['conversation'=>$conversationId,'sender'=>$userId,'body'=>$body]);$messageId=(int)$db->lastInsertId();$attached=MessageAttachmentService::attachUpload($db,dirname(__DIR__),$messageId,$userId,$upload);$db->commit();return(bool)$attached;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e instanceof RuntimeException?$e:new RuntimeException('We could not send that message. Please try again.');}
    }

    private static function assertConversationSafe(string $type,array $participants):void
    {
        $active=array_values(array_filter($participants,static fn(array $p):bool=>(bool)$p['active']));$roles=array_count_values(array_column($active,'participant_role'));$studentCount=(int)($roles['student']??0);$adultCount=(int)($roles['adult']??0);$guardianCount=(int)($roles['guardian']??0);if($studentCount>0&&$type!=='safeguarded')throw new RuntimeException('This conversation cannot accept messages because a student is present without safeguarded conversation status.');if($studentCount>1)throw new RuntimeException('Student-to-student messaging is not available.');if($studentCount>0){if($guardianCount<1)throw new RuntimeException('Messaging is paused because the required guardian is not present.');if($adultCount<1)throw new RuntimeException('This safeguarded conversation is incomplete and cannot accept messages.');}if($type==='safeguarded'&&$studentCount<1)throw new RuntimeException('This safeguarded conversation no longer has a student participant and requires review.');
    }

    private static function currentUser(PDO $db):array{$user=Auth::currentUser($db);if(!$user)throw new RuntimeException('Sign in to use Messages.');return$user;}
    private static function isStudentRole(string $role):bool{return str_contains(strtolower($role),'student');}
    private static function isStaffRole(string $role):bool{$role=strtolower($role);return str_contains($role,'staff')||str_contains($role,'manager')||str_contains($role,'admin')||str_contains($role,'director');}
    private static function isStudentUser(array $user):bool{return in_array('student',(array)($user['roles']??[]),true)||self::isStudentRole((string)($user['role']??''));}
    private static function isStaffUser(array $user):bool{return in_array('production_staff',(array)($user['roles']??[]),true)||in_array('administrator',(array)($user['roles']??[]),true)||self::isStaffRole((string)($user['role']??''));}
    private static function primaryGuardian(PDO $db,int $studentId):?array{$s=$db->prepare("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) name,u.display_role role,fr.relationship_type,fr.is_primary FROM family_relationships fr JOIN users u ON u.id=fr.guardian_user_id WHERE fr.student_user_id=:student AND fr.status='active' AND u.active=1 ORDER BY fr.is_primary DESC,fr.id LIMIT 1");$s->execute(['student'=>$studentId]);return$s->fetch()?:null;}
    private static function availableRecipients(PDO $db,array $user):array{$s=$db->prepare("SELECT id,CONCAT(first_name,' ',last_name) name,display_role role,initials FROM users WHERE active=1 AND id<>:user ORDER BY last_name,first_name");$s->execute(['user'=>(int)$user['id']]);$rows=$s->fetchAll();foreach($rows as &$r){$r['roles']=Auth::roles($db,(int)$r['id']);$r['student']=self::isStudentUser($r);$r['selectable']=!$r['student']||self::isStaffUser($user);}unset($r);return$rows;}
    private static function channels(PDO $db):array{return$db->query("SELECT c.id,c.name,c.channel_type,c.description,p.title production_title,COUNT(cp.id) post_count,MAX(cp.created_at) latest_at FROM channels c LEFT JOIN productions p ON p.id=c.production_id LEFT JOIN channel_posts cp ON cp.channel_id=c.id WHERE c.archived_at IS NULL GROUP BY c.id,c.name,c.channel_type,c.description,p.title,c.sort_order ORDER BY c.sort_order,c.name")->fetchAll();}
    private static function channelById(PDO $db,int $channelId):?array{if($channelId<1)return null;$s=$db->prepare("SELECT c.id,c.name,c.channel_type,c.description,p.title production_title FROM channels c LEFT JOIN productions p ON p.id=c.production_id WHERE c.id=:id AND c.archived_at IS NULL LIMIT 1");$s->execute(['id'=>$channelId]);$c=$s->fetch();if(!$c)return null;$p=$db->prepare("SELECT cp.id,cp.body,cp.pinned,cp.reactions_json,cp.created_at,CONCAT(u.first_name,' ',u.last_name) author,u.display_role author_role,u.initials FROM channel_posts cp JOIN users u ON u.id=cp.author_user_id WHERE cp.channel_id=:channel ORDER BY cp.pinned DESC,cp.created_at DESC");$p->execute(['channel'=>$channelId]);$c['posts']=$p->fetchAll();return$c;}

    private static function conversations(PDO $db,int $userId,string $query=''):array
    {
        $search='';$params=['user_id'=>$userId];if($query!==''){$search=" AND (c.subject LIKE :query OR EXISTS (SELECT 1 FROM messages sm WHERE sm.conversation_id=c.id AND sm.hidden_at IS NULL AND sm.body LIKE :query2))";$params['query']='%'.$query.'%';$params['query2']='%'.$query.'%';}
        $s=$db->prepare("SELECT c.id,c.subject,c.conversation_type,MAX(m.created_at) latest_at,COUNT(DISTINCT m.id) message_count,COUNT(DISTINCT cp.user_id) participant_count,(SELECT COUNT(*) FROM messages um WHERE um.conversation_id=c.id AND um.hidden_at IS NULL AND um.id>mine.last_read_message_id AND um.sender_user_id<>mine.user_id) unread_count FROM conversations c JOIN conversation_participants mine ON mine.conversation_id=c.id AND mine.user_id=:user_id JOIN conversation_participants cp ON cp.conversation_id=c.id LEFT JOIN messages m ON m.conversation_id=c.id AND m.hidden_at IS NULL WHERE 1=1 $search GROUP BY c.id,c.subject,c.conversation_type,mine.last_read_message_id,mine.user_id ORDER BY latest_at DESC,c.id DESC");$s->execute($params);return$s->fetchAll();
    }

    private static function conversationById(PDO $db,int $userId,int $conversationId):?array
    {
        if($conversationId<1)return null;$s=$db->prepare("SELECT c.id,c.subject,c.conversation_type FROM conversations c JOIN conversation_participants mine ON mine.conversation_id=c.id AND mine.user_id=:user WHERE c.id=:id LIMIT 1");$s->execute(['user'=>$userId,'id'=>$conversationId]);$conversation=$s->fetch();if(!$conversation)return null;$p=$db->prepare("SELECT cp.user_id,cp.participant_role,cp.guardian_required,u.active,CONCAT(u.first_name,' ',u.last_name) name,u.display_role role,u.initials FROM conversation_participants cp JOIN users u ON u.id=cp.user_id WHERE cp.conversation_id=:conversation ORDER BY FIELD(cp.participant_role,'student','guardian','adult'),u.last_name,u.first_name");$p->execute(['conversation'=>$conversationId]);$conversation['participants']=$p->fetchAll();$m=$db->prepare("SELECT m.id,m.body,m.created_at,m.sender_user_id,CONCAT(u.first_name,' ',u.last_name) sender,u.display_role sender_role,u.initials FROM messages m JOIN users u ON u.id=m.sender_user_id WHERE m.conversation_id=:conversation AND m.hidden_at IS NULL ORDER BY m.created_at,m.id");$m->execute(['conversation'=>$conversationId]);$conversation['messages']=$m->fetchAll();$attachments=MessageAttachmentService::forMessages($db,array_map(static fn(array $row):int=>(int)$row['id'],$conversation['messages']));foreach($conversation['messages'] as &$message)$message['attachments']=$attachments[(int)$message['id']]??[];unset($message);try{self::assertConversationSafe((string)$conversation['conversation_type'],$conversation['participants']);$conversation['send_allowed']=true;$conversation['safety_issue']=null;}catch(RuntimeException $e){$conversation['send_allowed']=false;$conversation['safety_issue']=$e->getMessage();}return$conversation;
    }

    private static function flash(string $type,string $message):void{$_SESSION['communication_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}

    private static function page(string $route,string $basePath,array $user,array $channels,array $conversations,array $recipients,?array $selectedChannel,?array $selectedConversation,string $query):never
    {
        $url=static fn(string $path):string=>($basePath?:'').$path;$esc=static fn(string $value):string=>htmlspecialchars($value,ENT_QUOTES,'UTF-8');$flash=$_SESSION['communication_flash']??null;unset($_SESSION['communication_flash']);$title=match($route){'/channels'=>'Community','/channels/view'=>$selectedChannel['name']??'Channel','/messages'=>'Messages','/messages/new'=>'New conversation',default=>$selectedConversation['subject']??'Conversation'};$section=str_starts_with($route,'/channels')?'Community':'Messages';header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=$esc($title)?> · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/communication-implementation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/message-attachments.css')?>"><style>@media(max-width:780px){body[data-native-route="messages-thread"] .comm-thread-layout .comm-participants{display:block!important;margin:10px 0 12px!important;padding:12px!important;border:.5px solid rgba(54,39,44,.11)!important;border-radius:14px!important;background:#fff!important;box-shadow:none!important}body[data-native-route="messages-thread"] .comm-participants>small{display:block!important;color:#a6192e!important;font-size:9px!important;font-weight:850!important;letter-spacing:.12em!important}body[data-native-route="messages-thread"] .comm-participants>h3{font-size:14px!important;margin:3px 0 8px!important}body[data-native-route="messages-thread"] .comm-participants>div{display:flex!important;align-items:center!important;gap:9px!important;padding:8px 0!important;border-top:.5px solid rgba(54,39,44,.11)!important}body[data-native-route="messages-thread"] .comm-participants>div:first-of-type{border-top:0!important}body[data-native-route="messages-thread"] .comm-participants i{width:30px!important;height:30px!important;display:grid!important;place-items:center!important;border-radius:50%!important;background:#f3ecee!important;color:#a6192e!important;font-style:normal!important;font-size:9px!important;font-weight:850!important}body[data-native-route="messages-thread"] .comm-participants span{display:grid!important}body[data-native-route="messages-thread"] .comm-participants b{font-size:12px!important}body[data-native-route="messages-thread"] .comm-participants span small{font-size:9px!important;color:#786d71!important}}</style></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader($section,$title,$basePath);?><div class="comm-page"><?php if($flash):?><div class="comm-flash <?=$esc($flash['type'])?>"><?=$esc($flash['message'])?></div><?php endif;?>
        <?php if($route==='/messages'):?><section class="comm-message-intro"><div><small>YOUR CONVERSATIONS</small><h2>Messages with the safety structure visible.</h2><p>Every conversation follows your account across productions. Search stays limited to conversations you actually participate in.</p></div><a class="button" href="<?=$url('/messages/new')?>">New conversation</a></section><form class="msg-search" method="get" action="<?=$url('/messages')?>"><input type="search" name="q" maxlength="100" value="<?=$esc($query)?>" placeholder="Search subjects and message text"><button type="submit">Search</button><?php if($query!==''):?><a href="<?=$url('/messages')?>">Clear</a><?php endif;?></form><div class="comm-conversation-list"><?php if(!$conversations):?><div class="comm-empty"><b><?=$query!==''?'No matching conversations':'No conversations yet'?></b><p><?=$query!==''?'Try a different search term.':'Start one with another CTSMD member.'?></p></div><?php endif;?><?php foreach($conversations as $conversation):$unread=(int)($conversation['unread_count']??0);?><a class="comm-conversation<?=$unread>0?' unread':''?>" href="<?=$url('/messages/thread?id='.(int)$conversation['id'])?>"><div class="comm-conversation-icon"><?=$conversation['conversation_type']==='safeguarded'?'●':'✉'?></div><div><small><?=$conversation['conversation_type']==='safeguarded'?'SAFEGUARDED':'DIRECT'?></small><h3><?=$esc($conversation['subject']?:'Conversation')?></h3><p><?=(int)$conversation['participant_count']?> participants · <?=(int)$conversation['message_count']?> messages</p></div><div class="comm-conversation-meta"><span><?=$conversation['latest_at']?$esc(date('M j · g:i A',strtotime($conversation['latest_at']))):'No messages'?></span><?php if($unread>0):?><strong class="comm-unread"><?=$unread?> new</strong><?php else:?><b>Open →</b><?php endif;?></div></a><?php endforeach;?></div>
        <?php elseif($route==='/messages/new'):?><section class="comm-channel-head"><div><small>NEW CONVERSATION</small><h2>Choose who you need to reach.</h2><p>Safety rules are resolved by the server. Required guardians cannot be removed or bypassed.</p></div><a href="<?=$url('/messages')?>">Cancel →</a></section><form class="comm-new-form" method="post" enctype="multipart/form-data" action="<?=$url('/messages/new')?>"><input type="hidden" name="csrf_token" value="<?=$esc((string)$_SESSION['communication_csrf'])?>"><input type="hidden" name="action" value="create_conversation"><label>Recipient<select name="recipient_id" required><option value="">Choose a member</option><?php foreach($recipients as $recipient):?><option value="<?=(int)$recipient['id']?>"<?=!$recipient['selectable']?' disabled':''?>><?=$esc($recipient['name'])?> — <?=$esc($recipient['role'])?><?=$recipient['student']&&!$recipient['selectable']?' (staff contact required)':''?></option><?php endforeach;?></select></label><label>Subject<input name="subject" maxlength="190" required></label><label>Opening message<textarea name="body" rows="6" maxlength="4000" required></textarea></label><label class="msg-attach-input">Attachment <small>optional</small><input type="file" name="attachment"></label><div class="comm-safety-banner"><div><b>Safety is automatic</b><span>Staff-to-student conversations remain safeguarded and include the active primary guardian automatically.</span></div><strong>SERVER ENFORCED</strong></div><div class="comm-new-actions"><a href="<?=$url('/messages')?>">Cancel</a><button class="button" type="submit">Create conversation</button></div></form>
        <?php elseif($route==='/messages/thread'):?><?php if(!$selectedConversation):?><section class="comm-empty"><b>Conversation not found</b><p>You may no longer have access to this conversation.</p><a class="button" href="<?=$url('/messages')?>">Back to Messages</a></section><?php else:?><section class="comm-thread-head"><div><small><?=$selectedConversation['conversation_type']==='safeguarded'?'SAFEGUARDED CONVERSATION':'DIRECT CONVERSATION'?></small><h2><?=$esc($selectedConversation['subject']?:'Conversation')?></h2><p><?=count($selectedConversation['participants'])?> participants</p></div><a href="<?=$url('/messages')?>">All messages →</a></section><?php if($selectedConversation['conversation_type']==='safeguarded'):?><div class="comm-safety-banner"><div><b>Guardian included</b><span>The student, CTSMD adult, and required guardian all receive this conversation.</span></div><strong>PROTECTED</strong></div><?php endif;?><div class="comm-thread-layout"><section class="comm-thread"><?php foreach($selectedConversation['messages'] as $message):$mine=(int)$message['sender_user_id']===(int)$user['id'];?><article class="comm-bubble<?=$mine?' mine':''?>"><header><i><?=$esc($message['initials'])?></i><span><b><?=$esc($message['sender'])?></b><small><?=$esc($message['sender_role'])?></small></span></header><p><?=nl2br($esc($message['body']))?></p><?php if($message['attachments']):?><div class="msg-attachments"><?php foreach($message['attachments'] as $attachment):?><a href="<?=$url('/messages/attachment?id='.(int)$attachment['id'])?>"><span>▣</span><div><b><?=$esc((string)$attachment['original_name'])?></b><small><?=StorageService::humanSize((int)$attachment['byte_size'])?> · <?=$esc(strtoupper((string)$attachment['extension']))?></small></div></a><?php endforeach;?></div><?php endif;?><time><?=$esc(date('M j · g:i A',strtotime($message['created_at'])))?></time></article><?php endforeach;?></section><aside class="comm-participants"><small>PARTICIPANTS</small><h3>Who can see this</h3><?php foreach($selectedConversation['participants'] as $participant):?><div><i><?=$esc($participant['initials'])?></i><span><b><?=$esc($participant['name'])?></b><small><?=$esc(ucfirst($participant['participant_role']))?> · <?=$esc($participant['role'])?></small></span></div><?php endforeach;?></aside></div><section class="comm-composer"><?php if($selectedConversation['send_allowed']):?><form method="post" enctype="multipart/form-data" action="<?=$url('/messages/thread?id='.(int)$selectedConversation['id'])?>"><input type="hidden" name="csrf_token" value="<?=$esc((string)$_SESSION['communication_csrf'])?>"><input type="hidden" name="action" value="send_message"><input type="hidden" name="conversation_id" value="<?=(int)$selectedConversation['id']?>"><label for="message-body">Reply to everyone in this conversation</label><textarea id="message-body" name="body" rows="3" maxlength="4000" required></textarea><label class="msg-attach-input">Attachment <small>optional</small><input type="file" name="attachment"></label><div><small><?=$selectedConversation['conversation_type']==='safeguarded'?'The guardian remains included automatically.':'Everyone listed above can see your reply and attachment.'?></small><button class="button" type="submit">Send message</button></div></form><?php else:?><div class="comm-send-blocked"><b>Sending is paused</b><p><?=$esc((string)$selectedConversation['safety_issue'])?></p></div><?php endif;?></section><?php endif;?>
        <?php elseif(str_starts_with($route,'/channels')):?><section class="comm-empty"><b>Community moved to the account-wide Community experience.</b><a class="button" href="<?=$url('/channels')?>">Open Community</a></section><?php endif;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
}
